import React from "react";
import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";

const Landing = () => {
  const navigate = useNavigate();

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.8 }}
      className="min-h-screen flex flex-col items-center justify-center text-center bg-gradient-to-br from-blue-900 via-blue-800 to-blue-950 text-white px-6"
    >
      <motion.h1
        initial={{ y: -20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.2, duration: 0.6 }}
        className="text-5xl font-bold mb-4"
      >
        Welcome to <span className="text-blue-300">AI Interview Coach</span>
      </motion.h1>

      <motion.p
        initial={{ y: 10, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.4, duration: 0.6 }}
        className="text-lg mb-8 max-w-2xl"
      >
        Get personalized feedback on your interviews powered by advanced AI.  
        Improve your confidence, communication, and performance — one question at a time.
      </motion.p>

      <div className="flex gap-6">
        <motion.button
          whileHover={{ scale: 1.05 }}
          onClick={() => navigate("/login")}
          className="bg-blue-600 px-6 py-3 rounded-lg font-semibold hover:bg-blue-700 transition"
        >
          Login
        </motion.button>

        <motion.button
          whileHover={{ scale: 1.05 }}
          onClick={() => navigate("/signup")}
          className="bg-blue-500 px-6 py-3 rounded-lg font-semibold hover:bg-blue-600 transition"
        >
          Sign Up
        </motion.button>
      </div>
    </motion.div>
  );
};

export default Landing;
